    pub fn set_text_style(&self, clip: u64, style: TextStyle, merge: bool, all: bool) -> Result<(), MobileError> {
        let mut s = self.lock();
        if all { text::set_style_everywhere(&mut s, &style) } else { text::set_style(&mut s, clip, &style, merge) }
    }

    /// The style preset `preset` (empty = the plain style) would give `clip`.
    pub fn text_preset_style(&self, clip: u64, preset: String) -> Result<TextStyle, MobileError> {
        let own = text::style(&self.lock(), clip)?;
        if preset.is_empty() {
            return Ok(text::plain_style(&own));
        }
        text::preset_style(&preset, &own).ok_or_else(|| MobileError::Command(format!("Unknown style {preset}.")))
    }

